public class AutoMLJobFactory(string resourceName = null, Action<Humidifier.SageMaker.AutoMLJob> factoryAction = null) : ResourceFactory<Humidifier.SageMaker.AutoMLJob>(resourceName)
{

    internal List<InnerAutoMLJobAutoMLJobChannelFactory> AutoMLJobInputDataConfigFactories { get; set; } = [];

    internal InnerAutoMLJobAutoMLComputeConfigFactory AutoMLComputeConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLOutputDataConfigFactory OutputDataConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLSecurityConfigFactory SecurityConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLJobObjectiveFactory AutoMLJobObjectiveFactory { get; set; }

    internal InnerAutoMLJobAutoMLDataSplitConfigFactory DataSplitConfigFactory { get; set; }

    internal InnerAutoMLJobAutoMLProblemTypeConfigFactory AutoMLProblemTypeConfigFactory { get; set; }

    protected override Humidifier.SageMaker.AutoMLJob Create()
    {
        var autoMLJobResult = CreateAutoMLJob();
        factoryAction?.Invoke(autoMLJobResult);

        return autoMLJobResult;
    }

    private Humidifier.SageMaker.AutoMLJob CreateAutoMLJob()
    {
        var autoMLJobResult = new Humidifier.SageMaker.AutoMLJob
        {
            GivenName = InputResourceName,
        };

        return autoMLJobResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.AutoMLJob result)
    {
        base.CreateChildren(result);

        result.AutoMLJobInputDataConfig = AutoMLJobInputDataConfigFactories.Any() ? AutoMLJobInputDataConfigFactories.Select(x => x.Build()).ToList() : null;
        result.AutoMLComputeConfig ??= AutoMLComputeConfigFactory?.Build();
        result.OutputDataConfig ??= OutputDataConfigFactory?.Build();
        result.SecurityConfig ??= SecurityConfigFactory?.Build();
        result.AutoMLJobObjective ??= AutoMLJobObjectiveFactory?.Build();
        result.DataSplitConfig ??= DataSplitConfigFactory?.Build();
        result.AutoMLProblemTypeConfig ??= AutoMLProblemTypeConfigFactory?.Build();
    }

} // End Of Class

